import sqlite3
import uuid
import difflib
import html
from datetime import datetime, timezone
from flask import Flask, request, jsonify, g, Response, abort

app = Flask(__name__)
DATABASE = 'db.sqlite3'


def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    conn.executescript('''
        CREATE TABLE IF NOT EXISTS entries (
            id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            created_by TEXT NOT NULL,
            last_modified_by TEXT NOT NULL,
            last_modified_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS edits (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            entry_id TEXT NOT NULL,
            content TEXT NOT NULL,
            modified_by TEXT NOT NULL,
            summary TEXT NOT NULL,
            modified_at TEXT NOT NULL,
            FOREIGN KEY (entry_id) REFERENCES entries(id)
        );
    ''')
    conn.commit()
    conn.close()


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def entry_to_dict(row):
    return {
        'id': row['id'],
        'title': row['title'],
        'content': row['content'],
        'lastModifiedBy': row['last_modified_by'],
        'lastModifiedAt': row['last_modified_at'],
    }


PAGE_STYLE = '''
<style>
body { font-family: -apple-system, Segoe UI, Roboto, sans-serif; max-width: 900px; margin: 2em auto; padding: 0 1em; color: #222; }
h1 { border-bottom: 2px solid #eee; padding-bottom: .3em; }
a { color: #0366d6; text-decoration: none; }
a:hover { text-decoration: underline; }
.meta { color: #666; font-size: .9em; margin-bottom: 1em; }
.content { white-space: pre-wrap; line-height: 1.5; background: #fafafa; padding: 1em; border-radius: 6px; border: 1px solid #eee; }
ul.entries { list-style: none; padding: 0; }
ul.entries li { padding: .5em 0; border-bottom: 1px solid #eee; }
.edit { border: 1px solid #eee; border-radius: 6px; padding: 1em; margin-bottom: 1em; }
.edit .meta { margin-bottom: .5em; }
.diff { font-family: monospace; font-size: .85em; white-space: pre-wrap; background: #fafafa; padding: .5em; border-radius: 4px; }
.diff .add { color: #22863a; background: #e6ffed; }
.diff .del { color: #b31d28; background: #ffeef0; }
.diff .ctx { color: #666; }
</style>
'''


def render_page(title, body):
    return f'''<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>{html.escape(title)}</title>
{PAGE_STYLE}
</head>
<body>
{body}
</body>
</html>'''


@app.route('/entries', methods=['GET'])
def list_entries():
    db = get_db()
    rows = db.execute('SELECT id, title, last_modified_at FROM entries ORDER BY title').fetchall()
    items = ''.join(
        f'<li><a href="/entries/{html.escape(r["id"])}">{html.escape(r["title"])}</a> '
        f'<span class="meta">(last modified {html.escape(r["last_modified_at"])})</span></li>'
        for r in rows
    )
    if not items:
        items = '<li><em>No entries yet.</em></li>'
    body = f'<h1>Wiki Entries</h1><ul class="entries">{items}</ul>'
    return Response(render_page('Wiki Entries', body), mimetype='text/html')


@app.route('/entries', methods=['POST'])
def create_entry():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid JSON body'}), 400
    title = data.get('title')
    content = data.get('content')
    created_by = data.get('createdBy')
    if not title or content is None or not created_by:
        return jsonify({'error': 'title, content and createdBy are required'}), 400

    entry_id = uuid.uuid4().hex
    ts = now_iso()
    db = get_db()
    db.execute(
        'INSERT INTO entries (id, title, content, created_by, last_modified_by, last_modified_at) '
        'VALUES (?, ?, ?, ?, ?, ?)',
        (entry_id, title, content, created_by, created_by, ts)
    )
    db.commit()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    return jsonify(entry_to_dict(row)), 201


@app.route('/entries/<entry_id>', methods=['GET'])
def get_entry(entry_id):
    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return Response(render_page('Not Found', '<h1>404 - Entry not found</h1>'), status=404, mimetype='text/html')

    contributors = db.execute(
        'SELECT DISTINCT modified_by FROM edits WHERE entry_id = ?', (entry_id,)
    ).fetchall()
    contrib_names = [c['modified_by'] for c in contributors]
    if row['created_by'] not in contrib_names:
        contrib_names.insert(0, row['created_by'])

    contrib_html = ', '.join(html.escape(c) for c in contrib_names) if contrib_names else 'None'
    body = f'''
    <h1>{html.escape(row['title'])}</h1>
    <div class="meta">
        Last modified by <strong>{html.escape(row['last_modified_by'])}</strong>
        at {html.escape(row['last_modified_at'])}<br>
        Contributors: {contrib_html}<br>
        <a href="/entries/{html.escape(row['id'])}/edits">View edit history</a>
    </div>
    <div class="content">{html.escape(row['content'])}</div>
    '''
    return Response(render_page(row['title'], body), mimetype='text/html')


@app.route('/entries/<entry_id>', methods=['PUT'])
def update_entry(entry_id):
    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return jsonify({'error': 'Entry not found'}), 404

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid JSON body'}), 400
    content = data.get('content')
    modified_by = data.get('modifiedBy')
    summary = data.get('summary')
    if content is None or not modified_by or summary is None:
        return jsonify({'error': 'content, modifiedBy and summary are required'}), 400

    ts = now_iso()
    db.execute(
        'INSERT INTO edits (entry_id, content, modified_by, summary, modified_at) VALUES (?, ?, ?, ?, ?)',
        (entry_id, content, modified_by, summary, ts)
    )
    db.execute(
        'UPDATE entries SET content = ?, last_modified_by = ?, last_modified_at = ? WHERE id = ?',
        (content, modified_by, ts, entry_id)
    )
    db.commit()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    return jsonify(entry_to_dict(row)), 200


def build_diff(old, new):
    old_lines = old.splitlines(keepends=True)
    new_lines = new.splitlines(keepends=True)
    diff = difflib.unified_diff(old_lines, new_lines, fromfile='previous', tofile='current', lineterm='')
    out = []
    for line in diff:
        escaped = html.escape(line.rstrip('\n'))
        if line.startswith('+') and not line.startswith('+++'):
            out.append(f'<span class="add">{escaped}</span>')
        elif line.startswith('-') and not line.startswith('---'):
            out.append(f'<span class="del">{escaped}</span>')
        else:
            out.append(f'<span class="ctx">{escaped}</span>')
    return '\n'.join(out)


@app.route('/entries/<entry_id>/edits', methods=['GET'])
def entry_edits(entry_id):
    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return Response(render_page('Not Found', '<h1>404 - Entry not found</h1>'), status=404, mimetype='text/html')

    edits = db.execute(
        'SELECT * FROM edits WHERE entry_id = ? ORDER BY modified_at ASC, id ASC', (entry_id,)
    ).fetchall()

    parts = [f'<h1>Edit history for {html.escape(row["title"])}</h1>',
             f'<p><a href="/entries/{html.escape(row["id"])}">&larr; Back to entry</a></p>']

    if not edits:
        parts.append('<p><em>No edits recorded yet.</em></p>')
    else:
        prev_content = row['content']
        # We need to reconstruct: the "previous" content for each edit is the content
        # before that edit. Since edits store the new content, we walk backwards.
        # Build list of contents: initial content is unknown from edits alone, but
        # the first edit's previous content is the entry's original content. We don't
        # store original separately, so we approximate by using the entry's current
        # content as the final state and reconstruct backwards.
        # Simpler: show diff of each edit against the previous edit's content,
        # and for the first edit against the entry's original content (which we
        # don't have). We'll show the first edit as a full addition.
        contents = [e['content'] for e in edits]
        for i, e in enumerate(edits):
            if i == 0:
                prev = ''
            else:
                prev = contents[i - 1]
            diff_html = build_diff(prev, e['content'])
            parts.append(f'''
            <div class="edit">
                <div class="meta">
                    <strong>{html.escape(e['modified_by'])}</strong> at {html.escape(e['modified_at'])}<br>
                    Summary: {html.escape(e['summary'])}
                </div>
                <div class="diff">{diff_html}</div>
            </div>
            ''')

    body = '\n'.join(parts)
    return Response(render_page(f'Edits - {row["title"]}', body), mimetype='text/html')


init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
